import React, { useState, useEffect, useCallback } from 'react'
import axios from 'axios'
import { PageTitle } from '../../../../_metronic/layout/core'
import { KTIcon } from '../../../../_metronic/helpers'

interface RolePermission {
    role: string
    permissions: string[]
}

const availableModules = [
    { id: 'dashboard', label: 'Dashboard' },
    { id: 'orders', label: 'All Orders' },
    { id: 'to-confirm', label: 'To Confirm' },
    { id: 'confirmed-orders', label: 'Confirmed' },
    { id: 'tracking', label: 'Tracking' },
    { id: 'products', label: 'Products' },
    { id: 'vendors', label: 'Vendors' },
    { id: 'intigo', label: 'Intigo' },
    { id: 'users', label: 'Users' },
    { id: 'history', label: 'History' },
    { id: 'bordereau', label: 'Bordereaux' },
    { id: 'sidebar-config', label: 'Sidebar Config' }
]

const roles = ['super admin', 'admin', 'seller', 'logistic']

const SidebarConfigPage: React.FC = () => {
    const [rolePermissions, setRolePermissions] = useState<RolePermission[]>([])
    const [loading, setLoading] = useState<boolean>(true)
    const [updatingRole, setUpdatingRole] = useState<string | null>(null)

    const fetchRolePermissions = useCallback(async () => {
        setLoading(true)
        try {
            const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8001/api';
            const response = await axios.get(`${apiUrl}/role-permissions`)
            if (response.data.success) {
                // Ensure all roles are present
                const data = response.data.role_permissions
                const merged = roles.map(r => {
                    const existing = data.find((p: any) => p.role === r)
                    return {
                        role: r,
                        permissions: existing ? existing.permissions : (r === 'admin' || r === 'super admin' ? availableModules.map(m => m.id) : ['dashboard'])
                    }
                })
                setRolePermissions(merged)
            }
        } catch (err) {
            console.error(err)
        } finally {
            setLoading(false)
        }
    }, [])

    useEffect(() => {
        fetchRolePermissions()
    }, [fetchRolePermissions])

    const toggleAccess = async (role: string, moduleId: string) => {
        const rp = rolePermissions.find(p => p.role === role)
        if (!rp) return

        const currentAccess = rp.permissions || []
        let newAccess: string[]
        if (currentAccess.includes(moduleId)) {
            newAccess = currentAccess.filter(id => id !== moduleId)
        } else {
            newAccess = [...currentAccess, moduleId]
        }

        setUpdatingRole(role)
        try {
            const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8001/api';
            const response = await axios.post(`${apiUrl}/role-permissions`, {
                role: role,
                permissions: newAccess
            })
            if (response.data.success) {
                setRolePermissions(prev => prev.map(p => p.role === role ? { ...p, permissions: newAccess } : p))
            }
        } catch (err) {
            console.error(err)
            alert('Error updating permissions')
        } finally {
            setUpdatingRole(null)
        }
    }

    return (
        <>
            <PageTitle breadcrumbs={[]}>Sidebar accessibility configuration</PageTitle>
            <div className='card mb-5 mb-xl-8'>
                <div className='card-header border-0 pt-5'>
                    <h3 className='card-title align-items-start flex-column'>
                        <span className='card-label fw-bold fs-3 mb-1'>Role Access Matrix</span>
                        <span className='text-muted mt-1 fw-semibold fs-7'>Manage module visibility for each role</span>
                    </h3>
                </div>
                <div className='card-body py-3'>
                    <div className='table-responsive'>
                        <table className='table table-row-bordered table-row-gray-100 align-middle gs-0 gy-3'>
                            <thead>
                                <tr className='fw-bold text-muted'>
                                    <th className='min-w-150px'>Role</th>
                                    {availableModules.map(module => (
                                        <th key={module.id} className='text-center min-w-80px fs-8 text-uppercase'>
                                            {module.label}
                                        </th>
                                    ))}
                                </tr>
                            </thead>
                            <tbody>
                                {loading ? (
                                    <tr><td colSpan={availableModules.length + 1} className='text-center py-10'>Loading permissions...</td></tr>
                                ) : (
                                    rolePermissions.map(rp => {
                                        const isAdminRole = rp.role === 'admin' || rp.role === 'super admin';
                                        let badgeColor = 'light'
                                        if (rp.role === 'super admin' || rp.role === 'admin') badgeColor = 'danger'
                                        if (rp.role === 'seller') badgeColor = 'success'
                                        if (rp.role === 'logistic') badgeColor = 'warning'

                                        return (
                                            <tr key={rp.role}>
                                                <td>
                                                    <div className='d-flex align-items-center'>
                                                        <span className={`badge badge-light-${badgeColor} fw-bold text-uppercase fs-7 px-3 py-2`}>
                                                            {rp.role}
                                                        </span>
                                                    </div>
                                                </td>
                                                {availableModules.map(module => (
                                                    <td key={module.id} className='text-center'>
                                                        <div className='form-check form-check-custom form-check-solid form-check-sm justify-content-center'>
                                                            <input
                                                                className='form-check-input'
                                                                type='checkbox'
                                                                checked={isAdminRole || (rp.permissions || []).includes(module.id)}
                                                                onChange={() => !isAdminRole && toggleAccess(rp.role, module.id)}
                                                                disabled={isAdminRole || updatingRole === rp.role}
                                                            />
                                                        </div>
                                                    </td>
                                                ))}
                                            </tr>
                                        )
                                    })
                                )}
                            </tbody>
                        </table>
                    </div>
                    <div className='alert alert-light-primary d-flex align-items-center p-5 mt-5'>
                        <KTIcon iconName='information-5' className='fs-2hx text-primary me-3' />
                        <div className='d-flex flex-column'>
                            <span className='fw-bold text-primary'>Role-Based Permissions</span>
                            <span className='fs-7 text-muted'>
                                Changes apply to all users with the selected role.
                                Admins and Super Admins always have full access.
                            </span>
                        </div>
                    </div>
                </div>
            </div>
        </>
    )
}

export default SidebarConfigPage
